const run = (seed) => {
  const world = new World({ seed, bounds });
  for (let i = 0; i < 5; i++)
    world.add({ x: 100 + world.random() * 400, y: 40, radius: 20 });
  world.advance(4); // simulate 4 seconds now
  return world.hash();
};
console.log("run 1:", run(7));
console.log("run 2:", run(7));
console.log("seed 8:", run(8));

